private void processDegreeInput(EditText degreeText, SeekArc seekArc) {
    String degreeStr = degreeText.getText().toString().trim();
    int degree;

    if (degreeStr.isEmpty()) {
        // Keep the value which was set for this servo before the field was cleared.
        // Values of other servos must never be used here.
        degree = getServoDegree(degreeText);
    } else {
        try {
            degree = Integer.parseInt(degreeStr);
        } catch (NumberFormatException e) {
            applyDegree(degreeText, seekArc, 0);
            toastInvalidValueMessage();
            return;
        }
    }

    if (degree > 360 || degree < 0) {
        applyDegree(degreeText, seekArc, 0);
        toastInvalidValueMessage();
    } else {
        applyDegree(degreeText, seekArc, degree);
    }
}

/**
 * Returns the last known degree value of the servo belonging to the given input field.
 */
private int getServoDegree(EditText degreeText) {
    Integer degree = servoDegrees.get(degreeText);
    return (degree == null) ? 0 : degree;
}

/**
 * Updates the input field of a servo after its seek arc has been moved.
 */
private void updateDegreeFromProgress(EditText degreeText, int progress) {
    int degree = (int) (progress * 3.6);
    servoDegrees.put(degreeText, degree);
    degreeText.setText(String.valueOf(degree));
    degreeText.setCursorVisible(false);
}

/**
 * Applies the given degree value to a single servo and remembers it as the current
 * value of that servo.
 */
private void applyDegree(EditText degreeText, SeekArc seekArc, int degree) {
    seekArc.setProgress((int) (degree / 3.6));
    // The seek arc resolution is coarser than a single degree, so the exact value is
    // restored after the progress change listener has updated the input field.
    servoDegrees.put(degreeText, degree);
    degreeText.setText(String.valueOf(degree));
    degreeText.setCursorVisible(false);
}
